<script>document.getElementById('closeGenerated').onclick=function(){document.getElementById('generatedModal').classList.remove('open')};</script>
<?php endif; endif; ?>
<div class="card"><h1>Mesa <?=$mesa['numero']?></h1><?php if($msg):?><div class="notice <?=strpos($msg,'No se')===0?'error':''?>"><?=h($msg)?></div><?php endif;?><?php if(!$comanda):?><form method="post"><input type="hidden" name="abrir" value="1"><button class="btn gold">Abrir comanda</button></form><?php else:?><div class="notice">Comanda #<?=$comanda['id']?> abierta desde <?=h($comanda['fecha_apertura'])?></div><div class="grid grid-2"><div><h2>Añadir consumo</h2><form method="post"><input type="hidden" name="add" value="1"><label>Producto</label><select name="plato_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=h($p['nombre'])?> · <?=money($p['precio_cup'])?></option><?php endforeach;?></select><label>Cantidad</label><input type="number" step="0.01" min="0.01" value="1" name="cantidad"><label>Notas</label><input name="notas" placeholder="Sin cebolla, etc."><button class="btn olive" style="margin-top:10px">Añadir a la mesa</button></form></div><div><h2>Consumo actual</h2><div class="table-wrap"><table><tr><th>Producto</th><th>Cant.</th><th>Subtotal</th></tr><?php foreach($items as $i):?><tr><td><?=h($i['nombre'])?></td><td><?=$i['cantidad']?></td><td class="gold"><?=money((float)$i['cantidad']*(float)$i['precio_unitario'])?></td></tr><?php endforeach;?><tr><th colspan="2">TOTAL</th><th class="gold"><?=money($total)?></th></tr></table></div><?php if($total>0):?><form method="post" style="margin-top:12px"><input type="hidden" name="cobrar" value="1"><label>Método de pago</label><select name="metodo"><option value="efectivo">Efectivo</option><option value="transferencia">Transferencia</option></select><label>Moneda recibida</label><select name="moneda"><?php foreach(availableCurrencies() as $c=>$n):?><option value="<?=$c?>"><?=$c?></option><?php endforeach;?></select><label>Monto recibido</label><input type="text" inputmode="decimal" name="monto" placeholder="Ej.: 7000 o 7.000" required><small class="muted">En efectivo puede recibir más que el total; RESpos calculará el vuelto.</small><label>Referencia de transferencia</label><input name="referencia"><div class="notice" style="margin-top:10px">Total a cobrar: <b><?=money((float)$total)?></b>. Si recibe efectivo superior al total, el vuelto se calcula automáticamente.</div><button class="btn gold" style="margin-top:10px;width:100%">Cobrar, cerrar mesa y generar documentos PDF</button></form><?php endif;?></div></div><?php endif;?></div><?php require_once __DIR__.'/../includes/footer.php';?>
